const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var thailand = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Thailand'));

  var april2016 = ee.DateRange('2016-04-01', '2016-04-30');
  var aprilBaseline = ee.DateRange('2001-04-01', '2010-04-30');

  // 2. Data Acquisition - MODIS LST (MOD11A2 8-day, 1km)
  var lstCol = ee.ImageCollection('MODIS/006/MOD11A2')
    .select('LST_Day_1km', 'QC_Day')
    .filterBounds(thailand);

  // Helper function to process LST
  function processLST(image) {
    var lst = image.select('LST_Day_1km')
      .multiply(0.02)  // Scale to Kelvin
      .subtract(273.15)  // Convert to Celsius
      .rename('LST_C');

    // Mask using QC (bits 0-1 = 00 for good quality)
    var qc = image.select('QC_Day');
    var mask = qc.bitwiseAnd(3).eq(0);
    return lst.updateMask(mask);
  }

  // Get April 2016 data
  var lst2016 = lstCol.filterDate(april2016).map(processLST);
  var lst2016Mean = lst2016.mean();

  // Get baseline data (2001-2010 Aprils)
  var lstBaseline = lstCol.filterDate(aprilBaseline).map(processLST);
  var lstBaselineMean = lstBaseline.mean();

  // 3. Check data availability
  var count2016 = lst2016.size().getInfo();
  var countBaseline = lstBaseline.size().getInfo();

  console.log('2016 April Images:', count2016);
  console.log('Baseline April Images (2001-2010):', countBaseline);

  if (count2016 === 0 || countBaseline === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Check valid pixels
  var stats2016 = lst2016Mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: thailand,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  var statsBaseline = lstBaselineMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: thailand,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  var pixels2016 = stats2016.LST_C || 0;
  var pixelsBaseline = statsBaseline.LST_C || 0;

  console.log('Valid Pixels 2016:', pixels2016);
  console.log('Valid Pixels Baseline:', pixelsBaseline);

  if (pixels2016 === 0 || pixelsBaseline === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean temperatures
  var mean2016 = lst2016Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: thailand,
    scale: 5000,
    maxPixels: 1e9
  }).get('LST_C').getInfo();

  var meanBaseline = lstBaselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: thailand,
    scale: 5000,
    maxPixels: 1e9
  }).get('LST_C').getInfo();

  console.log('Mean LST 2016 (°C):', mean2016);
  console.log('Mean LST Baseline (°C):', meanBaseline);

  // 6. Validation & Final Answer
  if (mean2016 === null || meanBaseline === null || 
      Math.abs(mean2016) > 60 || Math.abs(meanBaseline) > 60) {
    console.log('<answer>C3</answer>');
  } else if (mean2016 > meanBaseline) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
